const VERSION='cppinkplan-22dfc1c0890e1b';
const CORE=['./','index.html','presenter.html','Canon - Presenter Notes.html','Canon - Ink Planning Story.html',...Array.from({length:14},(_,i)=>'previews/slide-'+String(i+1).padStart(2,'0')+'.jpg')].map(p=>new URL(p,self.location).href);
self.addEventListener('install',e=>e.waitUntil((async()=>{const cache=await caches.open(VERSION);await cache.addAll(CORE);await self.skipWaiting();})()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('cppinkplan-')&&key!==VERSION)await caches.delete(key);await self.clients.claim();for(const c of await self.clients.matchAll())c.postMessage({type:'OFFLINE_READY'});})()));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;const url=new URL(e.request.url);url.search='';e.respondWith((async()=>{const cache=await caches.open(VERSION),saved=await cache.match(url.href);if(saved)return saved;try{return await fetch(e.request);}catch{if(e.request.mode==='navigate'){const name=decodeURIComponent(url.pathname).includes('Ink Planning Story')?'Canon - Ink Planning Story.html':'index.html';return await cache.match(new URL(name,self.location).href)||Response.error();}return Response.error();}})());});
self.addEventListener('message',e=>{if(e.data?.type==='CACHE_STATUS')e.waitUntil((async()=>{const c=await caches.open(VERSION);const ok=(await Promise.all(CORE.map(u=>c.match(u)))).every(Boolean);e.ports[0]?.postMessage({ready:ok,failed:!ok});})());});
